"""Resolve declared peer endpoints from live, optionally scoped Street views.

Only reciprocal original-span references enable a shared Smooth tangent or
an Exact offset-line miter. Geometry verifies the declaration; it never
discovers a connection. These fields are disposable input bindings, not
persistent Connector identities.
"""
from . import curved_corner_nodes as c
from .curved_network_ownership_nodes import _compare


def exact_profile_axis(g,chord,peer_chord):
    """Shared unit-offset miter, oriented away from the common endpoint.

    This does not change either centerline tangent. Reciprocal callers get
    opposite axes. Endpoint identity/coincidence must be checked by the caller.
    """
    own=c._unit(g,chord);peer=c._unit(g,peer_chord)
    denominator=1.-c._dot(own,peer)
    valid=g.math('GREATER_THAN',c._length(g,chord),1e-4)*g.math('GREATER_THAN',c._length(g,peer_chord),1e-4)
    valid=valid*g.math('GREATER_THAN',denominator,.125-1e-8)
    axis=c._scale(c._sub(c._right(own),c._right(peer)),
                  g.math('DIVIDE',1.,g.math('MAXIMUM',denominator,.001)))
    return axis,valid


def bind(g, sources, spans, row, start, count, edge_start, curve_first, curve_last, selected,
         *, interpolation=False, mode=None):
    keys=tuple('seam_'+side+'_'+key for side in ('start','end') for key in ('span','end','id'))
    existence=[]
    for key in keys:
        node=g.node('GeometryNodeInputNamedAttribute');node.data_type='INT'
        node.inputs['Name'].default_value='st_ps_'+key
        existence.append(c.V(g,node.outputs['Exists']))
    present=c._stat(g,spans,sum(existence))
    all_present=_compare(g,present,len(keys))
    valid=_compare(g,present,0)+all_present
    read=lambda key,at=row:c._read(g,spans,'st_ps_'+key,at,'INT')
    for end, side, name in ((0,'start','Start'),(1,'end','End')):
        peer,peer_end,jid=[read('seam_'+side+'_'+k) for k in ('span','end','id')]
        enabled=all_present*_compare(g,peer,0,'GREATER_EQUAL')
        empty=_compare(g,peer,-1)*_compare(g,peer_end,-1)*_compare(g,jid,-1)
        peer_ok=_compare(g,peer,0,'GREATER_EQUAL')*_compare(g,peer,c._count(g,spans),'LESS_THAN')
        peer_ok=peer_ok*(_compare(g,peer_end,0)+_compare(g,peer_end,1))*_compare(g,jid,0,'GREATER_EQUAL')
        pstart,pcount,pedge=[read(k,peer) for k in ('start','count','edge_start')]
        endpoint=c.choose(g,peer_end,pcount-1.,0,'INT')
        neighbor=c.choose(g,peer_end,pcount-2.,1,'INT')
        terminal=c.choose(g,peer_end,read('last',peer),read('first',peer),'INT')
        peer_ok=peer_ok*_compare(g,terminal,endpoint)*_compare(g,pcount,2,'GREATER_EQUAL')
        peer_ok=peer_ok*_compare(g,pstart,0,'GREATER_EQUAL')*_compare(g,pstart+pcount,c._count(g,sources),'LESS_EQUAL')
        def back(key):return c.choose(g,peer_end,read('seam_end_'+key,peer),read('seam_start_'+key,peer),'INT')
        back_span=back('span');back_end=back('end')
        peer_ok=peer_ok*_compare(g,back_span,0,'GREATER_EQUAL')*_compare(g,back_span,c._count(g,spans),'LESS_THAN')
        peer_ok=peer_ok*_compare(g,back_end,end)*_compare(g,back('id'),jid)
        for key,value in (('start',start),('count',count),('edge_start',edge_start)):
            peer_ok=peer_ok*_compare(g,read(key,back_span),value)
        peer_ok=peer_ok*_compare(g,read('last' if end else 'first',back_span),count-1. if end else 0)
        own_at=start+(count-1. if end else 0.)
        own_near=start+(count-2. if end else 1.)
        pos=lambda at:c._vec(g,c._sample(g,sources,g.position(),at,'FLOAT_VECTOR'))
        point=pos(own_at);other=pos(pstart+endpoint)
        chord=c._sub(pos(own_near),point);p_chord=c._sub(pos(pstart+neighbor),other)
        tangent=c._unit(g,c._sub(c._unit(g,chord),c._unit(g,p_chord)))
        peer_ok=peer_ok*g.math('GREATER_THAN',c._length(g,chord),1e-4)*g.math('GREATER_THAN',c._length(g,p_chord),1e-4)
        peer_ok=peer_ok*g.math('LESS_THAN',c._length(g,c._sub(point,other)),1e-5)
        peer_ok=peer_ok*g.math('GREATER_THAN',c._length(g,tangent),.99)
        # A seam cannot name the same original endpoint as both incidences.
        peer_ok=peer_ok*(1.-_compare(g,own_at,pstart+endpoint))
        touches=_compare(g,curve_last,count-1.) if end else _compare(g,curve_first,0)
        use_tangent=enabled*touches
        if interpolation:
            from . import curved_junction_nodes as boundary
            if mode is None:raise ValueError('Mode-aware seam binding requires the selected feature mode')
            exact=_compare(g,mode,0)
            peer_edge=pedge+c.choose(g,peer_end,pcount-2.,0,'INT')
            peer_mode=boundary._edge_sample(g,sources,c.named(g,'st_interpolation','INT'),peer_edge,'INT')
            peer_exact=_compare(g,peer_mode,0)
            compatible=peer_exact+_compare(g,peer_mode,3)
            axis,axis_valid=exact_profile_axis(g,chord,p_chord)
            # The Exact endpoint direction cannot move. At a mixed join its
            # ordinary normal is the common profile axis; the Smooth peer
            # adopts the opposite Exact tangent. No source control is moved.
            axis=c._pick(g,peer_exact,axis,c._right(c._unit(g,chord)))
            axis_valid=c.choose(g,peer_exact,axis_valid,1.)
            tangent=c._pick(g,peer_exact*(1.-exact),c._scale(c._unit(g,p_chord),-1.),tangent)
            peer_ok=peer_ok*c.choose(g,touches,compatible*c.choose(g,exact,axis_valid,1.),1.)
            g.bind(enabled*touches*exact,selected.inputs['Use '+name+' Profile Axis'])
            g.bind(g.xyz(*c._scale(axis,-1. if end else 1.)),selected.inputs[name+' Profile Axis'])
            use_tangent=use_tangent*(1.-exact)
        valid=valid*c.choose(g,all_present,c.choose(g,enabled,peer_ok,empty),1.)
        g.bind(use_tangent,selected.inputs['Use '+name+' Tangent'])
        g.bind(g.xyz(*c._scale(tangent,-1. if end else 1.)),selected.inputs[name+' Tangent'])
    return valid
